-- Import remaining self-contained app_config keys from the Sheets export:
-- dailyChecklist, overdueAlerts, flagConfig, launchChecklists,
-- rowingPassport, clubCalendars. No id remapping needed -- none of these
-- reference boats/locations/members by the old Sheets string ids.
--
-- rowingPassport had genuine source-data corruption in config.csv (not a
-- decoding artifact -- the corrupted bytes ARE valid UTF-8, just the
-- wrong codepoints): a two-character mojibake sequence stood in for
-- capital Thorn/Y-acute/U-acute in 13 spots, and a stray low-9 quote
-- character stood in for an intended right arrow in 4 spots (all within
-- one item, oar-transitions). Reconstructed from the raw CSV bytes and
-- verified against context (word meanings, the club's own name, and the
-- arrow's fit in a step-by-step description) before import.
--
-- staffStatus intentionally NOT imported: it is live on-duty state (who is
-- currently on duty right now), not historical config, and this staging
-- project already has current staffStatus written by verification testing
-- earlier in the migration -- overwriting it with the Sheet's stale
-- snapshot would be wrong, not merely redundant.

insert into public.app_config (key, value, updated_at) values ('dailyChecklist', '{"opening": [{"id": "62f5e68bca9545f8", "phase": "opening", "textEN": "Set out dog bowl", "textIS": "Hundaskál sett fram", "active": true, "sortOrder": 3}, {"id": "e50826a7ed624934", "phase": "opening", "textEN": "Get dressed for conditions & activity", "textIS": "Klæðist eftir veðri og verkefnum", "active": true, "sortOrder": 6}, {"id": "590bf0c84df24945", "phase": "opening", "textEN": "Raise flags", "textIS": "Hífa fána", "active": true, "sortOrder": 1}, {"id": "120d5d6a0f4d4a7e", "phase": "opening", "textEN": "Open dock & check/empty boats", "textIS": "Opna bryggju & yfirfara báta", "active": true, "sortOrder": 2}, {"id": "8faf9cca2e22456c", "phase": "opening", "textEN": "Group meeting: review weather & plan activity", "textIS": "Fundur: veður yfirfarið og dagsplan ákveðið", "active": true, "sortOrder": 5}, {"id": "b07f9da2db7b4087", "phase": "opening", "textEN": "Anticipate how tides will affect launching boats through the day", "textIS": "Áhrif sjávarfalla á sjósetningar yfir daginn metin", "active": true, "sortOrder": 7}, {"id": "7ad0226e3d0c4e8c", "phase": "opening", "textEN": "Check/clean changing rooms", "textIS": "Búningsklefar yfirfarnir og þrifnir", "active": true, "sortOrder": 8}, {"id": "181af1c6486d467a", "phase": "opening", "textEN": "Prepare equipment", "textIS": "Búnaður undirbúinn", "active": true, "sortOrder": 9}, {"id": "8aba1f9567a240c3", "phase": "opening", "textEN": "Update weather report", "textIS": "Uppfæra veðurspá", "active": true, "sortOrder": 4}], "closing": [{"id": "3c753ab1f13d46db", "phase": "closing", "textEN": "Make sure dock lines are secure and tidy", "textIS": "Bryggjulínur tryggilega festar og snyrtilegar", "active": true, "sortOrder": 1}, {"id": "810899dec1184f54", "phase": "closing", "textEN": "Refill fuel tanks if <50%", "textIS": "Eldsneytistankar fylltir ef undir 50%", "active": true, "sortOrder": 2}, {"id": "fa2be00300264aa6", "phase": "closing", "textEN": "Lock dock", "textIS": "Bryggja læst", "active": true, "sortOrder": 3}, {"id": "cac93d951f4947ca", "phase": "closing", "textEN": "Lower, fold, store flags", "textIS": "Fánar teknir niður, brotnir saman og gengið frá", "active": true, "sortOrder": 4}, {"id": "105f29eb6c674640", "phase": "closing", "textEN": "Dog bowl emptied & inside", "textIS": "Hundaskál tæmd og tekin inn", "active": true, "sortOrder": 5}, {"id": "050c6d83e72d4465", "phase": "closing", "textEN": "Empty hot pots", "textIS": "Hitabrúsar tæmdir", "active": true, "sortOrder": 6}, {"id": "b334ee634dc34629", "phase": "closing", "textEN": "Make sure boats are covered, tidy & secure on land", "textIS": "Bátar breiddir, snyrtilegir og tryggilega festir á landi", "active": true, "sortOrder": 7}, {"id": "dc97f1fb65a24399", "phase": "closing", "textEN": "Make sure all equipment is stored correctly & main space is tidy", "textIS": "Búnaður rétt gengið frá og aðalrými snyrtilegt", "active": true, "sortOrder": 8}, {"id": "14ae3fd0e7d845f3", "phase": "closing", "textEN": "Clean changing rooms, toilets", "textIS": "Búningsklefar og salerni þrifin", "active": true, "sortOrder": 9}, {"id": "42dd29fa887549e8", "phase": "closing", "textEN": "Empty/clean coffee machine, any dishes", "textIS": "Kaffivél og diskar tæmd og þrifin", "active": true, "sortOrder": 10}, {"id": "6bb8c406634f4a31", "phase": "closing", "textEN": "Tidy office & clean floor", "textIS": "Skrifstofa snyrt og gólf þrifin", "active": true, "sortOrder": 11}, {"id": "3e663ec3e5124ef4", "phase": "closing", "textEN": "Lights off & doors locked", "textIS": "Ljós slökkt og hurðir læstar", "active": true, "sortOrder": 12}]}'::jsonb, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();

