insert into public.app_config (key, value, updated_at) values ('flagConfig', '{"thresholds": {"yellow": 25, "orange": 50, "red": 65, "black": 80}, "wind": [{"maxBft": 4, "pts": 0}, {"maxBft": 5, "pts": 10}, {"maxBft": 6, "pts": 16}, {"maxBft": 7, "pts": 25}], "waves": [{"maxM": 0.5, "pts": 0}, {"maxM": 1, "pts": 3}, {"maxM": 1.3, "pts": 6}, {"maxM": 1.8, "pts": 8}, {"maxM": 2.1, "pts": 12}], "sst": [{"minC": 8, "pts": 1}, {"minC": 6, "pts": 2}, {"minC": 2, "pts": 4}, {"minC": -2, "pts": 8}], "feelsLike": [], "windDirModifier": {"dirs": ["NNE", "NE", "ENE", "E", "ESE", "SE", "ESE"], "pts": 8}, "gustModifier1Pts": 2, "gustModifier2Pts": 8, "visibility": {"good": 0, "reduced": 3, "poor": 15}, "flags": {"green": {"advice": "Good conditions – open to all sailing", "adviceIS": "Góðar aðstæður – opið öllum siglingum", "description": "Conditions are favorable for all boats & experience levels.", "descriptionIS": "Aðstæður eru góðar og henta öllum bátum og öllum reynslustigum."}, "yellow": {"advice": "Marginal conditions – experienced sailors or limited area", "adviceIS": "Jaðaraðstæður – aðeins reyndir siglingar", "description": "Conditions are marginal. Only experienced sailors with strong boat-handling skills should go out. Others may be able to sail within Fossvogur if staff and/or support boats are on duty.", "descriptionIS": "Aðstæður eru á mörkunum. Aðeins reynslumiklir siglarar ættu að halda á sjó. Aðrir geta mögulega siglt innan Fossvogs, ef starfsmenn og/eða gæslubátar eru á vakt."}, "orange": {"advice": "Difficult conditions – Limited vessels, safety cover required", "adviceIS": "Erfiðar aðstæður – Takmarkaðir bátar, öryggisgæsla nauðsynleg", "description": "Even with experience, conditions are only suited to certain vessels and rescues become risky and difficult. Club boats can only be taken out if the house is staffed and support boats are on the water.", "descriptionIS": "Aðstæður henta aðeins ákveðnum bátum og björgun getur verið erfið og áhættusöm. Klúbbbátar mega aðeins fara á sjó ef húsið er mönnuð og gæslubátar eru á vatni."}, "red": {"advice": "Hazardous conditions – staff or captains must approve all activity.", "adviceIS": "Hættulegar aðstæður – starfsfólk eða skipstjórar þurfa að samþykkja alla starfsemi.", "description": "Rescues with club equipment may not be possible. A captain or staff member must personally assess and authorize every checkout.", "descriptionIS": "Ekki er víst að björgun með búnaði klúbbsins sé möguleg. Skipstjóri eða starfsmaður skal meta aðstæður og veita leyfi fyrir hverri úttekt á bát."}, "black": {"advice": "Water closed – all sailing suspended.", "adviceIS": "Siglinasvæði lokað – allar siglingar stöðvaðar.", "description": "The water is closed to all sailing. All boats must remain ashore or return to harbor immediately. Check back later for updated conditions.", "descriptionIS": "Svæði er lokaður öllum siglingu. Allir bátar verða að vera á landi eða snara aftur til hafnar þegar á stað."}}}'::jsonb, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();

