insert into public.app_config (key, value, updated_at) values ('rowingPassport', '{"version": 4, "passports": [{"id": "rower", "name": {"EN": "rower", "IS": "rower"}, "promoteCertId": "rowing_division", "fromSub": "restricted", "toSub": "released", "requiredSigs": 2, "categories": [{"id": "technique", "name": {"EN": "Technique", "IS": "Tækni"}, "items": [{"id": "seat-position", "assessment": "practical", "module": 2, "name": {"EN": "Seat position", "IS": "Sætisstilling"}, "desc": {"EN": "The rower has practised adjusting their own position in the boat: Setting the stretcher: (1) Elbow/wrist distance from seat to stretcher footplate (on land). (2) Oars at 90 degrees out from the boat at a good set and with the body leaning slightly forward (on the water).", "IS": "Ræðarinn hefur æft að stilla sína eigin stöðu í bátnum: stilling á fótaspyrnu: (1) olnbogi/úlnliður fjarlægð frá sæti að fótaspyrnuplötu (á landi). (2) árar út í 90° frá bátnum við gott jafnvægi og með líkaminn aðeins fram boginn (á vatni)."}}, {"id": "click-discs", "assessment": "practical", "module": 5, "name": {"EN": "Click discs", "IS": "Smellskífur"}, "desc": {"EN": "The rower has practised using click discs to adjust draw height in the coastal boat", "IS": "on land and on the water"}}, {"id": "hand-position", "assessment": "practical", "module": 2, "name": {"EN": "Hand position", "IS": "Handstaða"}, "desc": {"EN": "The rower can place their hands correctly on the oars in a coastal boat", "IS": "Ræðarinn getur sett hendurnar rétt á árarnar í strandbáti."}}, {"id": "posture", "assessment": "practical", "module": 2, "name": {"EN": "Posture", "IS": "Líkamsstaða"}, "desc": {"EN": "The rower can row with correct posture (core engaged, parallel legs, relaxed shoulders) and can construct a full stroke step-by-step (arms only; add back; add slide).", "IS": "Ræðarinn getur róið með réttri líkamsstöðu (spenntur kjarni, samsíða fætur, slaknar axlir) og byggt upp heilt tog skref fyrir skref (aðeins armar; bætir við baki; bætir við rennu)."}}, {"id": "on-the-square", "assessment": "practical", "module": 4, "name": {"EN": "On the square", "IS": "á réttu"}, "desc": {"EN": "The rower understands the call and can row on the square", "IS": "Ræðarinn skilur kallið og getur róið á réttu"}}, {"id": "on-the-feather", "assessment": "practical", "module": 4, "name": {"EN": "On the feather", "IS": "á fjöður"}, "desc": {"EN": "The rower understands the call and can row on the feather", "IS": "Ræðarinn skilur kallið og getur róið á fjöður"}}, {"id": "way-enough", "assessment": "practical", "module": 4, "name": {"EN": "Way enough", "IS": "Nóg komið"}, "desc": {"EN": "The rower can understand and respond correctly and promptly to the command Way enough (set position with straight legs and arms", "IS": "oars horizontal and on the water surface in a coastal boat)"}}, {"id": "beginning-stroke", "assessment": "practical", "module": 4, "name": {"EN": "Beginning the stroke", "IS": "Upphaf togs"}, "desc": {"EN": "The rower can understand and respond correctly and promptly to the commands: 1) Ready to row (the rower is ready at the catch with the blade(s) vertical in the water", "IS": "floating in their own balance)"}}, {"id": "call-structure", "assessment": "theory", "module": 4, "name": {"EN": "Call structure", "IS": "Kallskipan"}, "desc": {"EN": "The rower understands the basic call structure (CALL in 2", "IS": "1"}}, {"id": "basic-stroke", "assessment": "practical", "module": 2, "name": {"EN": "Basic stroke", "IS": "Grunntog"}, "desc": {"EN": "The rower has practised rowing with a steady cadence and slow forward movement", "IS": "Ræðarinn hefur æft að róa með jöfnum takti og hæga framhreyfingu."}}, {"id": "following-cadence", "assessment": "practical", "module": 2, "name": {"EN": "Following cadence", "IS": "Að fylgja takti"}, "desc": {"EN": "The rower can follow the stroke seat without looking at their own oar", "IS": "Ræðarinn getur fylgt stýrisæti án þess að horfa á sína eigin ár."}}, {"id": "feathering", "assessment": "practical", "module": 4, "name": {"EN": "Feathering", "IS": "Fjöðrun"}, "desc": {"EN": "The rower has practised timely (early) feathering (ready for the catch)", "IS": "Ræðarinn hefur æft tímanlega (snemma) fjöðrun (tilbúinn fyrir gripið)."}}, {"id": "hold-water", "assessment": "practical", "module": 2, "name": {"EN": "Hold water/Check", "IS": "Halda vatni / Check"}, "desc": {"EN": "The rower can understand and respond promptly to the commands: 1) Hold water", "IS": "2) Check/Hard check"}}, {"id": "basic-backing", "assessment": "practical", "module": 2, "name": {"EN": "Basic backing", "IS": "Grunnbak"}, "desc": {"EN": "The rower can: 1) turn the blade for backing", "IS": "2) back using legs/arms and slide on the seat"}}, {"id": "compound-backing", "assessment": "practical", "module": 5, "name": {"EN": "Compound backing", "IS": "Samsett bak"}, "desc": {"EN": "The rower has practised: 1) backing and rowing alternately with the same rhythm and with seat slide", "IS": "2) backing and rowing simultaneously with straight legs and arms only"}}, {"id": "pressure", "assessment": "practical", "module": 4, "name": {"EN": "Pressure", "IS": "átak"}, "desc": {"EN": "The rower can understand the call and row at pressure", "IS": "Ræðarinn getur skilið kallið og róið at pressure (með fullu átaki)."}}, {"id": "blade-control", "assessment": "practical", "module": 4, "name": {"EN": "Blade control", "IS": "Blaðstjórn"}, "desc": {"EN": "The rower can control the oar correctly (the oar drops into the water and finds its own draw height; the oar is drawn horizontally through the water; the oar is pressed out of the water; the recovery (arms & hip/back) and seat slide (the square))", "IS": "Ræðarinn getur stjórnað árinni rétt (árin fellur í vatnið og finnur eigin dráttarhæð"}}, {"id": "let-it-run", "assessment": "practical", "module": 4, "name": {"EN": "Let it run", "IS": "Láta renna"}, "desc": {"EN": "The rower can demonstrate adequate set with the command let it run", "IS": "Ræðarinn getur sýnt fullnægjandi jafnvægi við kallið let it run."}}, {"id": "vary-stroke-length", "assessment": "practical", "module": 4, "name": {"EN": "Varying stroke length", "IS": "Breytileg toglengd"}, "desc": {"EN": "The rower can alternate between short strokes and normal/full strokes without changing cadence (both blades simultaneously or each side separately)", "IS": "Ræðarinn getur skipt á milli stuttra og venjulegra/fullra toga án þess að breyta takti (bæði blöðin samtímis eða hvora hlið fyrir sig)."}}, {"id": "quarter-oar-rowing", "assessment": "practical", "module": 4, "name": {"EN": "Quarter oar rowing", "IS": "Róður á fjórðungsár"}, "desc": {"EN": "The rower has practised rowing and backing with a quarter oar", "IS": "Ræðarinn hefur æft að róa og baka á fjórðungsár."}}, {"id": "quarter-oar-check", "assessment": "practical", "module": 4, "name": {"EN": "Quarter oar hold/check", "IS": "Stöðvun á fjórðungsár"}, "desc": {"EN": "The rower has practised oar on the water", "IS": "check/hard check with a quarter oar"}}, {"id": "watch-your-oar", "assessment": "practical", "module": 4, "name": {"EN": "Watch your oar", "IS": "Gættu árarinnar"}, "desc": {"EN": "The rower has practised Watch your oar", "IS": "where rowing continues and the rower takes responsibility for their own oars in the event of obstacles"}}, {"id": "crew-change", "assessment": "practical", "module": 3, "name": {"EN": "On-water crew change", "IS": "áhafnaskipti á vatni"}, "desc": {"EN": "The rower can demonstrate an on-water crew change", "IS": "Ræðarinn getur sýnt áhafnaskipti á vatni."}}, {"id": "seat-change", "assessment": "practical", "module": 3, "name": {"EN": "On-water seat change", "IS": "Sætaskipti á vatni"}, "desc": {"EN": "The rower can demonstrate an on-water seat change", "IS": "Ræðarinn getur sýnt sætaskipti á vatni."}}, {"id": "oar-transitions", "assessment": "practical", "module": 4, "name": {"EN": "Oar transitions", "IS": "Færsla ára"}, "desc": {"EN": "The rower has practised transitioning from normal rowing → to oar alongside → to oar out → to rowing resumes", "IS": "Ræðarinn hefur æft umbreytinguna frá venjulegum róðri → í ár samsíða báti"}}, {"id": "rowing-in-waves", "assessment": "practical", "module": 5, "name": {"EN": "Rowing in waves", "IS": "Róður í öldu"}, "desc": {"EN": "The rower has participated in and been informed about the basic principles of rowing", "IS": "steering and changing in waves"}}, {"id": "other-commands", "assessment": "practical", "module": 5, "name": {"EN": "Other commands", "IS": "önnur köll"}, "desc": {"EN": "The rower knows and can respond correctly to other commands beyond those listed above", "IS": "Ræðarinn þekkir og getur brugðist rétt við öðrum köllum en þeim sem talin eru upp hér að framan."}}]}, {"id": "support-boat", "name": {"EN": "Support boat protocols", "IS": "Gæslubátur"}, "items": [{"id": "sb-when-needed", "assessment": "theory", "module": 9, "name": {"EN": "When support boat is needed", "IS": "Þörf fyrir gæslubát"}, "desc": {"EN": "The rower can identify the conditions that make the support boat necessary.", "IS": "Ræðarinn getur greint þær aðstæður þar sem gæslubátur er nauðsynlegur."}}, {"id": "rescue-priorities", "assessment": "theory", "module": 9, "name": {"EN": "Rescue priorities", "IS": "Björgunarforgangur"}, "desc": {"EN": "The rower can identify the priorities in a rescue scenario and perform a basic scene assessment", "IS": "Ræðarinn getur greint forgangsröðun í björgunartilviki og framkvæmt grunnmat á vettvangi."}}, {"id": "fuel-fill", "assessment": "practical", "module": 9, "name": {"EN": "Refuel", "IS": "Eldsneytisáfylling"}, "desc": {"EN": "The rower can safely fill the fuel tank in a support boat", "IS": "Ræðarinn getur fyllt á eldsneytistank gæslubáts með öruggum hætti."}}, {"id": "correct-fuel", "assessment": "theory", "module": 9, "name": {"EN": "Correct fuel", "IS": "Rétt eldsneyti"}, "desc": {"EN": "The rower can identify which fuel is appropriate for which boat", "IS": "Ræðarinn getur greint hvaða eldsneyti hentar hverjum báti."}}, {"id": "fuel-level", "assessment": "practical", "module": 9, "name": {"EN": "Fuel level", "IS": "Eldsneytisstaða"}, "desc": {"EN": "The rower can accurately identify the fuel level in the boats (3+)", "IS": "Ræðarinn getur metið eldsneytisstöðu í bátunum (3+)."}}, {"id": "engine-start-kill", "assessment": "practical", "module": 9, "name": {"EN": "Engine start/kill", "IS": "Ræsing og stöðvun vélar"}, "desc": {"EN": "The rower can start and kill the engine on each support boat (3+)", "IS": "Ræðarinn getur ræst og stöðvað vél á hverjum gæslubáti (3+)."}}, {"id": "kill-cord-purpose", "assessment": "theory", "module": 9, "name": {"EN": "Kill cord purpose", "IS": "Tilgangur öryggissnúru"}, "desc": {"EN": "The rower can explain the purpose and importance of a kill cord", "IS": "Ræðarinn getur útskýrt tilgang og mikilvægi öryggissnúru (kill cord)."}}, {"id": "kill-cord-use", "assessment": "practical", "module": 9, "name": {"EN": "Kill cord use", "IS": "Notkun öryggissnúru"}, "desc": {"EN": "The rower demonstrates proper usage of the kill cord", "IS": "Ræðarinn sýnir rétta notkun öryggissnúru."}}, {"id": "leave-dock", "assessment": "practical", "module": 9, "name": {"EN": "Leave dock", "IS": "Frá bryggju"}, "desc": {"EN": "The rower can maneouver the support boat away from the dock in calm conditions", "IS": "Ræðarinn getur siglt gæslubátnum frá bryggju við kyrrar aðstæður."}}, {"id": "dock-boat", "assessment": "practical", "module": 9, "name": {"EN": "Dock boat", "IS": "Að bryggju"}, "desc": {"EN": "The rower can dock the support boat in calm conditions", "IS": "Ræðarinn getur lagt gæslubátnum við bryggju við kyrrar aðstæður."}}, {"id": "secure-boat", "assessment": "practical", "module": 9, "name": {"EN": "Secure boat", "IS": "Festa bát"}, "desc": {"EN": "The rower can secure the support boat appropriately", "IS": "Ræðarinn getur fest gæslubátinn á réttan hátt."}}, {"id": "knots", "assessment": "practical", "module": 9, "name": {"EN": "Knots", "IS": "Hnútar"}, "desc": {"EN": "The rower can demonstrate pelastikk", "IS": "hestahnútur"}}, {"id": "towing-risks", "assessment": "theory", "module": 9, "name": {"EN": "Towing risks", "IS": "áhætta við drátt"}, "desc": {"EN": "The rower can describe the risks of towing", "IS": "Ræðarinn getur lýst áhættu sem fylgir drætti."}}, {"id": "stern-tow", "assessment": "practical", "module": 9, "name": {"EN": "Stern tow", "IS": "Skutardráttur"}, "desc": {"EN": "The rower can demonstrate a stern tow using the bridle", "IS": "Ræðarinn getur sýnt skutardrátt með brúnu (bridle)."}}, {"id": "side-tow", "assessment": "practical", "module": 9, "name": {"EN": "Side tow", "IS": "Hliðardráttur"}, "desc": {"EN": "The rower can demonstrate a side tow using spring lines", "IS": "Ræðarinn getur sýnt hliðardrátt með spennulínum."}}, {"id": "approach-risks", "assessment": "theory", "module": 9, "name": {"EN": "Approach risks", "IS": "áhætta við nálgun"}, "desc": {"EN": "The rower can describe the risks and considerations of approaching boats and MOBs in the support boat", "IS": "Ræðarinn getur lýst áhættu og sjónarmiðum við nálgun að bátum og manni fyrir borð (MOB) í gæslubáti."}}, {"id": "upwind-approach", "assessment": "practical", "module": 9, "name": {"EN": "Upwind buoy approach", "IS": "Nálgun upp í vind"}, "desc": {"EN": "The rower can execute a controlled upwind approach to a buoy without making contact", "IS": "Ræðarinn getur framkvæmt stýrða nálgun upp í vind að bauju án þess að snerta hana."}}, {"id": "three-point-turn", "assessment": "practical", "module": 9, "name": {"EN": "3-point turn", "IS": "Þriggja punkta beygja"}, "desc": {"EN": "The rower can execute a tight", "IS": "controlled 3 point turn relative to a fixed point"}}, {"id": "mob-retrieval", "assessment": "theory", "module": 9, "name": {"EN": "MOB retrieval", "IS": "Endurheimt MOB"}, "desc": {"EN": "The rower can demonstrate 3+ ways to get an MOB into the support boat", "IS": "Ræðarinn getur sýnt 3 eða fleiri aðferðir til að ná manni fyrir borð upp í gæslubátinn."}}]}, {"id": "store-maintain", "name": {"EN": "Storage & Maintenance", "IS": "Geymsla og viðhald"}, "items": [{"id": "report-contacts", "assessment": "theory", "module": 6, "name": {"EN": "Reporting contacts", "IS": "Tilkynningatengiliðir"}, "desc": {"EN": "The rower knows who to contact and how with equipment concerns", "IS": "incidents"}}, {"id": "rig-derig", "assessment": "practical", "module": 5, "name": {"EN": "Rig & derig", "IS": "Uppsetning og niðurtekt"}, "desc": {"EN": "The rower can rig and derig the boat correctly", "IS": "Ræðarinn getur sett upp og tekið niður bátinn á réttan hátt."}}, {"id": "post-trip-cleaning", "assessment": "practical", "module": 2, "name": {"EN": "Post-trip cleaning", "IS": "Þrif eftir ferð"}, "desc": {"EN": "The rower has participated in retrieving and cleaning the boat and has been informed about the manual for Washing and preparation after a trip (located at the PC) and about correct placement of oars during cleaning", "IS": "Ræðarinn hefur tekið þátt í að sækja og þrífa bátinn og fengið kynningu á handbókinni Þvottur og undirbúningur eftir ferð (við tölvuna) og um rétta staðsetningu ára við þrif."}}, {"id": "cleaning-rationale", "assessment": "theory", "module": 2, "name": {"EN": "Cleaning rationale", "IS": "ástæður þrifa"}, "desc": {"EN": "The rower can explain how to clean equipment and understands the rationale", "IS": "Ræðarinn getur útskýrt hvernig á að þrífa búnað og skilur hvers vegna það skiptir máli."}}, {"id": "boathouse-placement", "assessment": "practical", "module": 5, "name": {"EN": "Boathouse placement", "IS": "Setja í bátaskýli"}, "desc": {"EN": "The rower has participated in placing the boat in the boathouse", "IS": "Ræðarinn hefur tekið þátt í að setja bátinn í bátaskýlið."}}, {"id": "boat-storage", "assessment": "practical", "module": 5, "name": {"EN": "Boat storage", "IS": "Bátageymsla"}, "desc": {"EN": "The rower has familiarised themselves with proper boat storage", "IS": "Ræðarinn þekkir rétta geymslu báta."}}, {"id": "damage-log", "assessment": "practical", "module": 3, "name": {"EN": "Damage log", "IS": "Tjónaskráning"}, "desc": {"EN": "The rower has been informed that damage must be logged on the Ýmir app and how to do so", "IS": "Ræðarinn hefur fengið fræðslu um að skrá skemmdir á Ýmir-appinu og hvernig það er gert."}}, {"id": "slings-use", "assessment": "practical", "module": 2, "name": {"EN": "Slings use", "IS": "Notkun burðaróla"}, "desc": {"EN": "The rower can demonstrate the use of slings", "IS": "Ræðarinn getur sýnt notkun burðaróla."}}, {"id": "prep-manuals", "assessment": "practical", "module": 5, "name": {"EN": "Preparation manuals", "IS": "Undirbúningshandbækur"}, "desc": {"EN": "The rower has familiarised themselves with the manuals for Washing and preparation after a trip and Preparation before going on the water (posted in the boathouse)", "IS": "Ræðarinn þekkir handbækurnar Þvottur og undirbúningur eftir ferð og Undirbúningur fyrir ferð á vatn (í bátaskýlinu)."}}]}, {"id": "safety-protocols", "name": {"EN": "Safety protocols", "IS": "öryggisreglur"}, "items": [{"id": "prohibited-conditions", "assessment": "theory", "module": 1, "name": {"EN": "Prohibited conditions", "IS": "Bannaðar aðstæður"}, "desc": {"EN": "The rower can identify the conditions when rowing is prohibited without extraordinary safety considerations.", "IS": "Ræðarinn getur greint þær aðstæður þar sem róður er óheimilt án sérstakra öryggisráðstafana."}}, {"id": "cold-water-clothing", "assessment": "theory", "module": 1, "name": {"EN": "Cold-water clothing", "IS": "Klæðnaður í köldu vatni"}, "desc": {"EN": "The rower can discuss and effectively justify proper clothing for active training in cold-water regimes", "IS": "understanding risks and trade-offs"}}, {"id": "swim-50m", "assessment": "practical", "module": 1, "name": {"EN": "Swim 50m clothed", "IS": "50 m sund í fötum"}, "desc": {"EN": "The rower can swim 50m in clothes they are likely to train in", "IS": "Ræðarinn getur synt 50 m í þeim fötum sem hann er líklegur til að æfa í."}}, {"id": "tread-water", "assessment": "practical", "module": 1, "name": {"EN": "Tread water", "IS": "Flotæfing"}, "desc": {"EN": "The rower can tread water for two minutes.", "IS": "Ræðarinn getur flotið á vatni í tvær mínútur."}}, {"id": "emergency-landings", "assessment": "practical", "module": 3, "name": {"EN": "Emergency landings", "IS": "Neyðarlendingarstaðir"}, "desc": {"EN": "The rower can identify emergency landing sites around Skerjafjörður on a chart and when they might be used", "IS": "Ræðarinn getur greint neyðarlendingarstaði í Skerjafirði á sjókorti og hvenær þeirra er þörf."}}, {"id": "signal-for-help", "assessment": "theory", "module": 1, "name": {"EN": "Signal for help", "IS": "Neyðarmerki"}, "desc": {"EN": "The rower can identify 3 or more ways to signal for assistance", "IS": "Ræðarinn getur nefnt 3 eða fleiri leiðir til að gefa neyðarmerki."}}, {"id": "id-hand-signals", "assessment": "theory", "module": 1, "name": {"EN": "Identify hand signals", "IS": "Þekkja handmerki"}, "desc": {"EN": "The rower can identify basic hand signals", "IS": "Ræðarinn getur greint grunnhandmerki."}}, {"id": "perform-hand-signals", "assessment": "practical", "module": 1, "name": {"EN": "Perform hand signals", "IS": "Framkvæma handmerki"}, "desc": {"EN": "The rower can perform basic hand signals", "IS": "Ræðarinn getur framkvæmt grunnhandmerki."}}, {"id": "local-risks", "assessment": "theory", "module": 3, "name": {"EN": "Local fixed risks", "IS": "Staðbundnar áhættur"}, "desc": {"EN": "The rower can describe the local fixed risks in Skerjafjörður", "IS": "Ræðarinn getur lýst föstum staðbundnum áhættum í Skerjafirði."}}, {"id": "local-weather", "assessment": "theory", "module": 3, "name": {"EN": "Local weather knowledge", "IS": "Staðbundið veðurfar"}, "desc": {"EN": "The rower demonstrates nuanced local knowledge of weather effects in Skerjafjörður", "IS": "Ræðarinn sýnir blæbrigðaríka þekkingu á veðurfari í Skerjafirði."}}, {"id": "head-underwater", "assessment": "practical", "module": 1, "name": {"EN": "Head underwater", "IS": "Höfuð undir vatni"}, "desc": {"EN": "The rower can comfortably have their head underwater", "IS": "Ræðarinn getur látið höfuðið þægilega undir vatn."}}, {"id": "capsize-drill", "assessment": "practical", "module": 3, "name": {"EN": "Capsize drill", "IS": "Veltuæfing"}, "desc": {"EN": "The rower executes a capsize drill with oars", "IS": "Ræðarinn framkvæmir veltuæfingu með árum."}}, {"id": "mob-drill", "assessment": "practical", "module": 3, "name": {"EN": "MOB drill", "IS": "MOB-æfing"}, "desc": {"EN": "The rower has participated in an MOB drill", "IS": "Ræðarinn hefur tekið þátt í æfingu um mann fyrir borð (MOB)."}}, {"id": "mob-response", "assessment": "theory", "module": 3, "name": {"EN": "MOB response", "IS": "Viðbrögð við MOB"}, "desc": {"EN": "The rower can describe the steps of an MOB response", "IS": "Ræðarinn getur lýst þeim skrefum sem fylgja þegar maður fer fyrir borð."}}, {"id": "capsize-response", "assessment": "theory", "module": 3, "name": {"EN": "Capsize response", "IS": "Viðbrögð við veltu"}, "desc": {"EN": "The rower can explain the appropriate response to a capsize", "IS": "Ræðarinn getur útskýrt rétt viðbrögð við veltu."}}, {"id": "right-reenter", "assessment": "practical", "module": 3, "name": {"EN": "Right & re-enter", "IS": "Rétting og innkoma"}, "desc": {"EN": "The rower can demonstrate righting the boat and re-entry in two or more ways without oars", "IS": "Ræðarinn getur sýnt að rétta bátinn og komast aftur um borð með tveimur eða fleiri aðferðum án ára."}}, {"id": "one-ten-sixty", "assessment": "theory", "module": 3, "name": {"EN": "1-10-60 principle", "IS": "1-10-60 reglan"}, "desc": {"EN": "The rower can explain the 1-10-60 principle", "IS": "Ræðarinn getur útskýrt 1-10-60 regluna."}}, {"id": "cold-vs-hypo", "assessment": "theory", "module": 3, "name": {"EN": "Cold challenge vs hypothermia", "IS": "Kuldi vs ofkæling"}, "desc": {"EN": "The rower can describe the difference between a cold challenge and mild hypothermia", "IS": "Ræðarinn getur lýst muninum á kuldaáreiti og vægri ofkælingu."}}, {"id": "hypo-levels", "assessment": "theory", "module": 3, "name": {"EN": "Hypothermia levels", "IS": "Stig ofkælingar"}, "desc": {"EN": "The rower can describe the difference between mild/moderate and severe hypothermia", "IS": "Ræðarinn getur lýst muninum á vægri/miðlungs og alvarlegri ofkælingu."}}, {"id": "treat-hypo", "assessment": "theory", "module": 3, "name": {"EN": "Treat hypothermia", "IS": "Meðferð ofkælingar"}, "desc": {"EN": "The rower can describe how to treat mild/moderate and severe hypothermia and the risks involved", "IS": "Ræðarinn getur lýst meðferð á vægri/miðlungs og alvarlegri ofkælingu og þeirri áhættu sem henni fylgir."}}, {"id": "cold-injury", "assessment": "theory", "module": 3, "name": {"EN": "Cold injuries", "IS": "Kuldaskaðar"}, "desc": {"EN": "The rower can describe chilblains and other cold injuries and how to prevent them", "IS": "Ræðarinn getur lýst frostbólum og öðrum kuldaskaða og hvernig má koma í veg fyrir þá."}}, {"id": "dehydration", "assessment": "theory", "module": 3, "name": {"EN": "Dehydration", "IS": "Vökvaskortur"}, "desc": {"EN": "The rower can describe the risks", "IS": "s/sx of dehydration and its impact"}}, {"id": "heat-illness", "assessment": "theory", "module": 3, "name": {"EN": "Heat illness", "IS": "Hitatengd veikindi"}, "desc": {"EN": "The rower understands the risk of heat-related illness", "IS": "Ræðarinn skilur áhættu hitatengdra veikinda."}}, {"id": "uv-exposure", "assessment": "theory", "module": 3, "name": {"EN": "UV exposure", "IS": "UV-geislun"}, "desc": {"EN": "The rower understands the risk of UV exposure on the water", "IS": "Ræðarinn skilur áhættu UV-geislunar á vatni."}}, {"id": "safety-course-1", "assessment": "practical", "name": {"EN": "Safety course 1", "IS": "Öryggisnámskeið 1"}, "desc": {"EN": "The rower has watched Safety Course Part 1 (video) and completed the test at https://www.aarhusroklub.dk/sikkerhedskursus-for-nyemedlemmer/sikkerhedskursus", "IS": "Ræðarinn hefur horft á hluta 1 af öryggisnámskeiðinu (myndband) og lokið prófinu á https://www.aarhusroklub.dk/sikkerhedskursus-for-nyemedlemmer/sikkerhedskursus"}, "retired": true}, {"id": "safety-at-sea", "assessment": "practical", "name": {"EN": "Safety at sea", "IS": "Öryggi á sjó"}, "desc": {"EN": "The rower has been informed about safety at sea and the club''s rowing regulations, and that these can be found on the club''s website", "IS": "Ræðarinn hefur fengið fræðslu um öryggi á sjó og reglur klúbbsins um róður og veit að þær er að finna á vef klúbbsins."}, "retired": true}, {"id": "safety-course-2", "assessment": "practical", "name": {"EN": "Safety course 2", "IS": "Öryggisnámskeið 2"}, "desc": {"EN": "The rower has watched Safety Course Part 2 (video) and completed the test (same URL as Part 1)", "IS": "Ræðarinn hefur horft á hluta 2 af öryggisnámskeiðinu (myndband) og lokið prófinu (sama slóð og hluti 1)."}, "retired": true}, {"id": "safety-course-3", "assessment": "practical", "name": {"EN": "Safety course 3", "IS": "Öryggisnámskeið 3"}, "desc": {"EN": "The rower has watched Safety Course Part 3 (video) and completed the test", "IS": "Ræðarinn hefur horft á hluta 3 af öryggisnámskeiðinu (myndband) og lokið prófinu."}, "retired": true}]}, {"id": "safety-equipment", "name": {"EN": "Safety equipment", "IS": "öryggisbúnaður"}, "items": [{"id": "don-pfd-land", "assessment": "practical", "module": 1, "name": {"EN": "Don PFD on land", "IS": "Vesti á landi"}, "desc": {"EN": "The rower can correctly put on a life jacket on land", "IS": "Ræðarinn getur sett björgunarvesti rétt á sig á landi."}}, {"id": "fit-companion-pfd", "assessment": "practical", "module": 1, "name": {"EN": "Fit companion PFD", "IS": "Stilla vesti félaga"}, "desc": {"EN": "The rower can test the fit of a companion''s life jacket", "IS": "Ræðarinn getur athugað hvort björgunarvesti félaga sé rétt stillt."}}, {"id": "don-pfd-boat", "assessment": "practical", "module": 3, "name": {"EN": "Don PFD in boat", "IS": "Vesti í bát"}, "desc": {"EN": "The rower can correctly put on (and remove) a life jacket in the boat", "IS": "Ræðarinn getur sett á sig og tekið af sér björgunarvesti í bátnum."}}, {"id": "don-pfd-water", "assessment": "practical", "module": 3, "name": {"EN": "Don PFD in water", "IS": "Vesti í vatni"}, "desc": {"EN": "The rower can correctly put on a life jacket in water", "IS": "Ræðarinn getur sett björgunarvesti rétt á sig í vatni."}}, {"id": "pfd-cold-water", "assessment": "theory", "module": 3, "name": {"EN": "PFD in cold water", "IS": "Vesti í köldu vatni"}, "desc": {"EN": "The rower can explain the importance of a life jacket in cold water", "IS": "Ræðarinn getur útskýrt mikilvægi björgunarvestis í köldu vatni."}}, {"id": "pfd-rules", "assessment": "theory", "module": 1, "name": {"EN": "PFD rules", "IS": "Reglur um björgunarvesti"}, "desc": {"EN": "The rower can explain the rules around life jackets", "IS": "Ræðarinn getur útskýrt reglur um notkun björgunarvestis."}}, {"id": "floatation-vs-pfd", "assessment": "theory", "module": 1, "name": {"EN": "Floatation vs PFD", "IS": "Flothjálp vs björgunarvesti"}, "desc": {"EN": "The rower can explain the difference between a floatation aid/PFD & life jacket", "IS": "Ræðarinn getur útskýrt muninn á flothjálp/PFD og björgunarvesti."}}, {"id": "shell-safety-gear", "assessment": "theory", "module": 3, "name": {"EN": "Shell safety gear", "IS": "öryggisbúnaður í ræðarbát"}, "desc": {"EN": "The rower can explain what safety equipment is on board the rowing shell", "IS": "Ræðarinn getur útskýrt hvaða öryggisbúnaður er um borð í ræðarbátnum."}}, {"id": "stow-shell-gear", "assessment": "practical", "module": 3, "name": {"EN": "Stow shell gear", "IS": "Geymsla búnaðar í ræðarbát"}, "desc": {"EN": "The rower demonstrates how to stow safety equipment on the rowing shell", "IS": "Ræðarinn sýnir hvernig á að geyma öryggisbúnað í ræðarbátnum."}}, {"id": "sb-safety-gear", "assessment": "theory", "module": 9, "name": {"EN": "Support boat gear", "IS": "öryggisbúnaður gæslubáts"}, "desc": {"EN": "The rower can explain what safety equipment is on the support boat", "IS": "Ræðarinn getur útskýrt hvaða öryggisbúnaður er í gæslubátnum."}}, {"id": "sb-gear-stow", "assessment": "practical", "module": 3, "name": {"EN": "SB gear stow/retrieve", "IS": "Sækja og geyma búnað"}, "desc": {"EN": "The rower demonstrates where to retrieve and where to stow safety equipment for the support boat.", "IS": "Ræðarinn sýnir hvar á að sækja og hvar á að geyma öryggisbúnað gæslubátsins."}}, {"id": "comms-equipment", "assessment": "practical", "module": 3, "name": {"EN": "Comms equipment", "IS": "Fjarskiptabúnaður"}, "desc": {"EN": "The rower can demonstrate usage and describe the limitations of available communication equipment on the water", "IS": "Ræðarinn getur sýnt notkun og lýst takmörkunum þess fjarskiptabúnaðar sem er tiltækur á vatni."}}, {"id": "emergency-numbers", "assessment": "theory", "module": 1, "name": {"EN": "Emergency numbers", "IS": "Neyðarnúmer"}, "desc": {"EN": "The rower demonstrates knowledge of the primary emergency contact numbers", "IS": "Ræðarinn þekkir helstu neyðarsímanúmer."}}]}, {"id": "launch-land", "name": {"EN": "Launching/Landing", "IS": "Sjósetning og lending"}, "items": [{"id": "launch-trolley", "assessment": "practical", "module": 5, "name": {"EN": "Launch with trolley", "IS": "Sjósetning með vagni"}, "desc": {"EN": "The rower has practised launching a coastal boat using a boat trolley and knows where a coastal boat may be lifted", "IS": "Ræðarinn hefur æft að sjósetja strandbát með bátavagni og veit hvar má lyfta strandbáti."}}, {"id": "launch-float-dock", "assessment": "practical", "module": 2, "name": {"EN": "Launch from float dock", "IS": "Sjósetning af flotbryggju"}, "desc": {"EN": "The rower has practiced launching a boat from the float dock", "IS": "Ræðarinn hefur æft að sjósetja bát af flotbryggjunni."}}, {"id": "place-oars", "assessment": "practical", "module": 2, "name": {"EN": "Place & secure oars", "IS": "Setja árar á bát"}, "desc": {"EN": "The rower can place and secure the oars on the boat", "IS": "Ræðarinn getur sett og fest árarnar á bátinn."}}, {"id": "boarding", "assessment": "practical", "module": 2, "name": {"EN": "Boarding", "IS": "Að fara um borð"}, "desc": {"EN": "The rower has practised boarding", "IS": "including using an oar for balance"}}, {"id": "gate-step-in", "assessment": "practical", "module": 2, "name": {"EN": "Gate release & step in", "IS": "Losa lás og stíga um borð"}, "desc": {"EN": "The rower can release gate locks", "IS": "use oars for balance"}}, {"id": "ship-oars", "assessment": "practical", "module": 2, "name": {"EN": "Ship oars", "IS": "Taka inn árar"}, "desc": {"EN": "The rower can understand and respond correctly to the call ship oars", "IS": "Ræðarinn getur skilið og brugðist rétt við kallinu ship oars."}}, {"id": "log-trip-end", "assessment": "practical", "module": 5, "name": {"EN": "Log trip completion", "IS": "Skrá ferðalok"}, "desc": {"EN": "The rower understands how to log trip completion.", "IS": "Ræðarinn veit hvernig á að skrá lok ferðar."}}, {"id": "lifting-technique", "assessment": "practical", "module": 2, "name": {"EN": "Lifting technique", "IS": "Lyftingartækni"}, "desc": {"EN": "The rower has practised correct lifting technique and knows the correct lifting points on a coastal boat", "IS": "Ræðarinn hefur æft rétta lyftingartækni og veit hvar á að lyfta strandbáti."}}, {"id": "pre-trip-prep", "assessment": "practical", "module": 5, "name": {"EN": "Pre-trip preparation", "IS": "Undirbúningur fyrir ferð"}, "desc": {"EN": "The rower has participated in preparation and has been informed about the manual for preparation (Preparation before going on the water) (posted in the boathouse)", "IS": "Ræðarinn hefur tekið þátt í undirbúningi og fengið kynningu á handbókinni Undirbúningur fyrir ferð á vatn (í bátaskýlinu)."}}, {"id": "pontoon-approach", "assessment": "practical", "module": 4, "name": {"EN": "Pontoon approach", "IS": "Koma að flotbryggju"}, "desc": {"EN": "The rower has been oriented on how to come alongside the club pontoon (Short strokes", "IS": "aim for the corner of the pontoon on the side you wish to approach"}}, {"id": "log-trip-start", "assessment": "practical", "module": 5, "name": {"EN": "Log trip start", "IS": "Skrá upphaf ferðar"}, "desc": {"EN": "The rower knows how to log the beginning of a trip/the check-out process and whose responsibility it is.", "IS": "Ræðarinn veit hvernig á að skrá upphaf ferðar/útskráningarferlið og hver ber ábyrgð á því."}}]}, {"id": "ergometer", "name": {"EN": "Ergometer", "IS": "Róðrarvél"}, "items": [{"id": "erg-hours", "assessment": "practical", "module": 7, "name": {"EN": "Erg hours logged", "IS": "Tímar á róðrarvél"}, "desc": {"EN": "The rower has logged X hours on an erg", "IS": "Ræðarinn hefur skráð X klukkustundir á róðrarvél."}}, {"id": "erg-technique-theory", "assessment": "theory", "module": 1, "name": {"EN": "Erg technique (theory)", "IS": "Tækni á róðrarvél (bóklegt)"}, "desc": {"EN": "The rower can explain proper erg technique (not in the presence of the erg)", "IS": "Ræðarinn getur útskýrt rétta tækni á róðrarvél (án þess að vera við vélina)."}}, {"id": "erg-technique-demo", "assessment": "practical", "module": 1, "name": {"EN": "Erg technique (demo)", "IS": "Tækni á róðrarvél (sýning)"}, "desc": {"EN": "The rower can demonstrate proper erg technique", "IS": "Ræðarinn getur sýnt rétta tækni á róðrarvél."}}, {"id": "drag-setting", "assessment": "theory", "module": 1, "name": {"EN": "Drag setting", "IS": "Viðnámsstilling"}, "desc": {"EN": "The rower can describe the effect of drag & how to approximate on-water conditions", "IS": "Ræðarinn getur lýst áhrifum viðnámsstillingar og hvernig má líkja eftir aðstæðum á vatni."}}]}, {"id": "community", "name": {"EN": "Community", "IS": "Samfélag"}, "items": [{"id": "club-intro", "assessment": "theory", "module": 6, "name": {"EN": "Club intro", "IS": "Kynning á klúbbnum"}, "desc": {"EN": "The rower has been told about Ýmir''s organisation", "IS": "culture"}}, {"id": "program-fluidity", "assessment": "theory", "module": 6, "name": {"EN": "Program fluidity", "IS": "Sveigjanleiki í verkferlum"}, "desc": {"EN": "The rower understands that the early nature of the program means that protocols will be fluid at the start", "IS": "mutual accountability will be important"}}, {"id": "winter-maintenance", "assessment": "theory", "module": 6, "name": {"EN": "Winter maintenance", "IS": "Vetrarviðhald"}, "desc": {"EN": "The rower has been informed about the necessity of winter maintenance", "IS": "Ræðarinn hefur fengið fræðslu um mikilvægi vetrarviðhalds."}}]}, {"id": "boat", "name": {"EN": "Boat structure and function", "IS": "Bygging og virkni báts"}, "items": [{"id": "safe-stepping", "assessment": "practical", "module": 2, "name": {"EN": "Safe stepping", "IS": "örugg skref"}, "desc": {"EN": "The rower has been informed about safe stepping positions in a coastal boat", "IS": "Ræðarinn hefur fengið fræðslu um öruggar stöður til að stíga í strandbáti."}}, {"id": "rower-positions", "assessment": "practical", "module": 1, "name": {"EN": "Rower positions", "IS": "Staðsetning ræðara"}, "desc": {"EN": "The rower knows starboard and port and the rowers'' positions in the boat from bow to stern (1-2-3-4)", "IS": "Ræðarinn þekkir stjórnborða og bakborða og staðsetningar ræðara í bátnum frá stafni að skut (1-2-3-4)."}}, {"id": "port-starboard", "assessment": "theory", "module": 1, "name": {"EN": "Port/starboard", "IS": "Bakborði og stjórnborði"}, "desc": {"EN": "The rower can identify port and starboard both as an observer and a rower", "IS": "Ræðarinn getur greint bakborða og stjórnborða bæði sem áhorfandi og sem ræðari."}}, {"id": "boat-parts", "assessment": "theory", "module": 1, "name": {"EN": "Boat parts", "IS": "Hlutar báts"}, "desc": {"EN": "The rower can identify basic parts of the boat: bow", "IS": "stern"}}, {"id": "oar-parts", "assessment": "theory", "module": 1, "name": {"EN": "Oar parts", "IS": "Hlutar árar"}, "desc": {"EN": "The rower can identify the basic parts of a sculling oar: handle", "IS": "shaft"}}, {"id": "buoyancy", "assessment": "theory", "module": 2, "name": {"EN": "Buoyancy", "IS": "Uppdrif"}, "desc": {"EN": "The rower can explain buoyancy of the boat and the intention behind its design", "IS": "Ræðarinn getur útskýrt uppdrif bátsins og hugmyndafræðina að baki hönnun hans."}}, {"id": "skeg-function", "assessment": "theory", "module": 2, "name": {"EN": "Skeg function", "IS": "Virkni skegs"}, "desc": {"EN": "The rower can explain the function of the skeg and how to position it in a coastal boat", "IS": "Ræðarinn getur útskýrt virkni skegsins og hvernig á að stilla hann í strandbáti."}}]}, {"id": "audits", "name": {"EN": "Audits", "IS": "Úttektir"}, "items": [{"id": "first-audit", "assessment": "practical", "module": 7, "name": {"EN": "First audit", "IS": "Fyrsta úttekt"}, "desc": {"EN": "First audited practice complete", "IS": "Fyrstu úttektaræfingu lokið."}}, {"id": "second-audit", "assessment": "practical", "module": 7, "name": {"EN": "Second audit", "IS": "önnur úttekt"}, "desc": {"EN": "Second audited practice complete", "IS": "Annarri úttektaræfingu lokið."}}, {"id": "third-audit", "assessment": "practical", "module": 7, "name": {"EN": "Third audit", "IS": "Þriðja úttekt"}, "desc": {"EN": "Third audited practice complete", "IS": "Þriðju úttektaræfingu lokið."}}, {"id": "capsize-recovery-audit", "assessment": "practical", "module": 7, "name": {"EN": "Capsize recovery audit", "IS": "Úttekt á sjálfsbjörg"}, "desc": {"EN": "The rower performs an unassisted capsize recovery (with oars) during an audited practice", "IS": "Ræðarinn framkvæmir sjálfstæða endurkomu eftir veltu (með árum) á úttektaræfingu."}}, {"id": "stern-tow-audit", "assessment": "practical", "module": 7, "name": {"EN": "Stern tow audit", "IS": "Úttekt á skutardrætti"}, "desc": {"EN": "The rower performs a successful", "IS": "safe stern tow during an audited practice"}}, {"id": "side-tow-audit", "assessment": "practical", "module": 7, "name": {"EN": "Side tow audit", "IS": "Úttekt á hliðardrætti"}, "desc": {"EN": "The rower performs a successful", "IS": "safe side tow using spring lines during an audited practice."}}]}]}]}'::jsonb, now())
